def _code_bytes() -> bytes:
    """Isi kode gabungan (loader + semua bagian), dipakai sidik jari cache supaya mengedit bagian mana pun membatalkan cache lama."""
    chunks = [open(_os.path.abspath(__file__), "rb").read()]
    for _n in _PART_FILES:
        chunks.append(open(_os.path.join(_PARTS_DIR, _n), "rb").read())
    return b"".join(chunks)


def _load_parts() -> None:
    _flags = _future.annotations.compiler_flag
    _g = globals()
    for _n in _PART_FILES:
        _p = _os.path.join(_PARTS_DIR, _n)
        with open(_p, "rb") as _f:
            _code = compile(_f.read(), _p, "exec", flags=_flags, dont_inherit=True)
        exec(_code, _g)


_load_parts()
